function editGroup(id=null){const g=groups.find(g=>g.id===id),d=panel(`<form id="groupForm"><div class="eyebrow">MORE VOICES, MORE STORIES</div><h2>${g?'编辑':'创建'}群聊</h2><label>群聊名字<input name="groupName" required maxlength="40" value="${escapeHtml(g?.name||'')}"></label><label>群聊氛围<textarea name="description" rows="3" maxlength="2000" placeholder="例如：朋友们的小茶会…">${escapeHtml(g?.prompt||'')}</textarea></label><div class="group-members">${roles.map(r=>`<label class="member-option">${avatarHTML('role:'+r.id,r.emoji)}<span>${escapeHtml(r.name)}</span><input type="checkbox" name="members" value="${r.id}" ${g?.members.includes(r.id)?'checked':''}></label>`).join('')}</div><p class="api-note">选择 2–6 位角色，每轮会为各角色分别调用一次 API。群聊有独立的长期记忆。</p><div class="actions"><button class="secondary" type="button" id="cancelGroup">取消</button><button class="primary">保存群聊</button></div></form>`);$('#cancelGroup').onclick=()=>d.close();$('#groupForm').onsubmit=e=>{e.preventDefault();const f=e.target,members=[...f.querySelectorAll('[name="members"]:checked')].map(x=>x.value);if(members.length<2||members.length>6){toast('请选择 2–6 位角色');return}const group={id:id||'group:'+crypto.randomUUID(),name:f.groupName.value.trim(),emoji:'♧',prompt:f.description.value.trim(),members};if(!group.name)return;groups=id?groups.map(x=>x.id===id?group:x):[...groups,group];localSave('groups',groups);d.close();current=group.id;go('chat');toast('群聊已保存')}}
function renderChatList(){
  screen.innerHTML=`<section class="view">${title('私语信箱','LET’S TALK, DEAR','<button class="round" id="chatAdd" aria-label="创建角色或群聊">+</button>')}<div class="chat-links"><button id="openMoments">❀ 朋友圈</button><button id="openGroups">♧ 建群聊</button><button id="openMemories">♧ 记忆花园</button></div><div class="notice">${apiReady()?'✧ API 已连接，今天想聊些什么？':'先连接 API，再开启聊天。 <button id="chatApi">去设置 ↗</button>'}</div><div id="roleList"></div></section>`;
  const list=$('#roleList');[...groups,...roles].forEach(r=>{const b=document.createElement('button');b.className='role';const last=(histories[r.id]||[]).at(-1);b.innerHTML=`${avatarHTML('role:'+r.id,r.emoji)}<div class="info"><strong>${escapeHtml(r.name)}${r.members?' <span class="mini-tag">群聊</span>':''}</strong><p>${escapeHtml(last?.content||'你的故事，等你开启。')}</p></div><span class="arrow">›</span>`;b.onclick=()=>{current=r.id;render()};list.append(b)});
  $('#chatAdd').onclick=()=>{const d=panel('<h2>新的相遇</h2><button class="menu-button" id="addCharacter">创建角色 <span>＋</span></button><button class="menu-button" id="addGroup">创建群聊 <span>＋</span></button><button class="secondary full" id="closeAdd">取消</button>');$('#addCharacter').onclick=()=>{d.close();editRole()};$('#addGroup').onclick=()=>{d.close();editGroup()};$('#closeAdd').onclick=()=>d.close()};
  $('#openMoments').onclick=()=>go('moments');$('#openGroups').onclick=()=>editGroup();$('#openMemories').onclick=()=>go('memory');if($('#chatApi'))$('#chatApi').onclick=()=>go('api');
}
function renderMoments(){screen.innerHTML=`<section class="view">${title('朋友圈','LITTLE MOMENTS, BIG FEELINGS','<button class="round" id="newMoment" aria-label="发布动态">+</button>')}<div class="moment-cover"><span>❀</span><h3>把日常，酿成温柔。</h3><p>你与角色们的私人朋友圈</p></div><div class="actions"><select id="momentRole" aria-label="选择发布动态的角色">${roles.map(r=>`<option value="${r.id}">${escapeHtml(r.name)}</option>`).join('')}</select><button class="secondary" id="roleMoment">生成角色动态</button></div><p class="api-note">角色动态与评论通过你的 API 生成；这里的内容仅保存到你的小手机。</p><div id="momentList"></div></section>`;
  $('#newMoment').onclick=()=>createMoment();$('#roleMoment').onclick=async()=>{if(!requireAPI())return;const r=roles.find(r=>r.id===$('#momentRole').value);if(!r){toast('先创建角色');return}const b=$('#roleMoment');b.disabled=true;b.textContent='正在构思…';try{const text=await request({...config,key},[{role:'system',content:PalaisCore.systemPrompt(r,worldbook,[])+'\n'+memoryPrompt(r.id)+'\n你要发布一条符合人设的朋友圈动态。只写动态正文，20–100字，不使用红包格式。'},{role:'user',content:'写一条今天的日常动态。'}],400);moments.unshift({id:crypto.randomUUID(),author:r.id,text,createdAt:Date.now(),liked:false,comments:[]});localSave('moments',moments);if(tab==='moments')renderMoments();toast('角色动态已生成')}catch(err){toast(friendly(err))}finally{b.disabled=false;b.textContent='生成角色动态'}};
  const list=$('#momentList');if(!moments.length)list.innerHTML='<div class="soft-empty">发布第一条动态，收藏今天。</div>';moments.forEach(m=>{const r=roles.find(r=>r.id===m.author),card=document.createElement('article');card.className='moment-card';card.innerHTML=`<div class="moment-person">${avatarHTML(m.author==='me'?'profile':'role:'+m.author,r?.emoji||'🎀')}<div><strong>${escapeHtml(m.author==='me'?profile.name:r?.name||'角色')}</strong><small>${new Date(m.createdAt).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></div></div><p>${escapeHtml(m.text)}</p>${mediaCache.has('moment:'+m.id)?`<img class="moment-photo" alt="动态配图" src="${mediaCache.get('moment:'+m.id)}">`:''}<div class="moment-tools"><button class="text-button like">${m.liked?'♥ 已喜欢':'♡ 喜欢'}</button><button class="text-button comment">评论</button><button class="text-button ai-comment">角色评论</button><button class="text-button remove">删除</button></div><div class="moment-comments">${(m.comments||[]).map(c=>`<div><strong>${escapeHtml(c.author==='me'?profile.name:chatLabel(c.author))}：</strong>${escapeHtml(c.text)}</div>`).join('')}</div>`;
    card.querySelector('.like').onclick=()=>{m.liked=!m.liked;localSave('moments',moments);renderMoments()};card.querySelector('.comment').onclick=()=>commentMoment(m);card.querySelector('.ai-comment').onclick=()=>commentMoment(m,true);card.querySelector('.remove').onclick=()=>{const d=panel('<h2>删除这条动态？</h2><div class="actions"><button class="secondary" id="keepMoment">取消</button><button class="primary" id="deleteMoment">删除</button></div>');$('#keepMoment').onclick=()=>d.close();$('#deleteMoment').onclick=async()=>{moments=moments.filter(x=>x.id!==m.id);localSave('moments',moments);await mediaWrite('moment:'+m.id,null);d.close();renderMoments()}};list.append(card)});
}
function createMoment(){const id=crypto.randomUUID(),d=panel(`<form id="momentForm"><h2>今天的小片刻</h2><label>动态内容<textarea name="text" required maxlength="3000" rows="5" placeholder="写下今天想留住的瞬间…"></textarea></label>${fileInput('momentFile')}<div id="momentImagePreview"></div><button class="text-button" type="button" id="chooseMomentPhoto">＋ 添加一张图片</button><div class="actions"><button type="button" class="secondary" id="cancelMoment">取消</button><button class="primary" id="publishMoment">发布动态</button></div></form>`);let image=null;$('#cancelMoment').onclick=()=>d.close();$('#chooseMomentPhoto').onclick=()=>$('#momentFile').click();$('#momentFile').onchange=async e=>{const b=$('#publishMoment');b.disabled=true;try{image=await prepareImage(e.target.files[0],1200);$('#momentImagePreview').innerHTML=`<img alt="动态图片预览" class="moment-photo" src="${image}">`}catch(err){toast(err.message)}finally{b.disabled=false}};$('#momentForm').onsubmit=async e=>{e.preventDefault();const text=e.target.text.value.trim();if(!text)return;const b=$('#publishMoment');b.disabled=true;try{if(image)await mediaWrite('moment:'+id,image);const next=[{id,author:'me',text,createdAt:Date.now(),liked:false,comments:[]},...moments];localSave('moments',next);moments=next;d.close();renderMoments();toast('动态已发布')}catch(err){toast(err.message)}finally{b.disabled=false}}}
function commentMoment(m,ai=false){const d=panel(`<form id="commentForm"><h2>${ai?'请角色评论':'留一句话'}</h2>${ai?`<label>选择角色<select name="roleId">${roles.map(r=>`<option value="${r.id}">${escapeHtml(r.name)}</option>`).join('')}</select></label>`:'<label>评论<textarea name="text" required rows="3" maxlength="1000"></textarea></label>'}<div class="actions"><button type="button" class="secondary" id="cancelComment">取消</button><button class="primary" id="submitComment">${ai?'生成评论':'发布评论'}</button></div></form>`);$('#cancelComment').onclick=()=>d.close();$('#commentForm').onsubmit=async e=>{e.preventDefault();const f=e.target,b=$('#submitComment');b.disabled=true;try{let author='me',text;if(ai){if(!apiReady())throw Error('请先连接 API');author=f.roleId.value;const r=roles.find(r=>r.id===author);if(!r)throw Error('请先创建角色');text=await request({...config,key},[{role:'system',content:r.prompt+'\n'+memoryPrompt(r.id)+'\n根据人设为下面的朋友圈动态留一条自然的中文评论，只输出评论内容，不使用红包格式。'},{role:'user',content:m.text}],300)}else text=f.text.value.trim();if(!text)return;m.comments.push({author,text,createdAt:Date.now()});localSave('moments',moments);d.close();renderMoments();toast('评论已保存')}catch(err){toast(friendly(err))}finally{b.disabled=false}}}
function cardHTML(m){if(!m.card)return '';const c=m.card;return `<div class="gift-card ${c.type==='redpacket'?'packet':'transfer'}"><div class="gift-main"><span>${c.type==='redpacket'?'福':'↗'}</span><div><strong>${c.type==='redpacket'?'心意红包':'暖心转账'} · ¥${escapeHtml(c.amount)}</strong><small>${escapeHtml(c.note||'一点小小的心意')}</small></div></div><div class="gift-foot">虚拟互动 · ${c.status==='received'?'已领取':m.role==='user'?'已发送':'待领取'}</div>${m.role==='assistant'&&c.status==='pending'?`<button class="receive-card" data-receive="${m.id}">${c.type==='redpacket'?'拆开红包':'收下心意'}</button>`:''}</div>`}
function sendGift(r){if(busy){toast('等本轮回复完成后再发送');return}const d=panel(`<form id="giftForm"><h2>送一份小心意</h2><label>卡片类型<select name="kind"><option value="redpacket">红包</option><option value="transfer">转账</option></select></label><label>金额<input name="amount" type="number" min="0.01" max="100000" step="0.01" required placeholder="例如：52.00"></label><label>留言<input name="note" maxlength="80" placeholder="愿你今天开心"></label><p class="api-note">这是角色扮演卡片，不涉及真实资金。</p><div class="actions"><button type="button" class="secondary" id="cancelGift">取消</button><button class="primary">发送卡片</button></div></form>`);$('#cancelGift').onclick=()=>d.close();$('#giftForm').onsubmit=e=>{e.preventDefault();const f=e.target,amount=Number(f.amount.value);if(!Number.isFinite(amount)||amount<=0||amount>100000)return;const card={type:f.kind.value,amount:amount.toFixed(2),note:f.note.value.trim(),status:'sent'};d.close();sendMessage(r,card.note||'送给你的一点心意。',card)}}
